theory.code:
RBAC:  Uzytkownik "anna" -> rola "EDITOR" -> {articles:read, articles:write}
       Uzytkownik "jan"  -> rola "VIEWER" -> {articles:read}

ABAC:  canViewOwnOrderOnly(requestingUser, order):
           return requestingUser.equals(order.ownerUsername())
       -> decyzja zalezy od RELACJI konkretnego uzytkownika z konkretnym zasobem,
          nie da sie tego wyrazic jedna, stala rola

Map<String, Set<String>> rolePermissions = Map.of(
    "EDITOR", Set.of("articles:read", "articles:write"),
    "VIEWER", Set.of("articles:read")
);
Map<String, String> userRoles = Map.of("anna", "EDITOR", "jan", "VIEWER");

boolean hasPermission(String username, String permission) {
    String role = userRoles.get(username);
    if (role == null) return false;
    return rolePermissions.getOrDefault(role, Set.of()).contains(permission);
}
// hasPermission("jan", "articles:write") -> false (VIEWER nie ma tego uprawnienia)

record Order(int id, String ownerUsername, double total) {}

boolean canViewOwnOrderOnly(String requestingUser, Order order) {
    return requestingUser.equals(order.ownerUsername());
}

Order orderA = new Order(1, "anna", 150.0);
canViewOwnOrderOnly("anna", orderA); // true - Anna jest wlascicielem
canViewOwnOrderOnly("jan", orderA);  // false - Jan probuje zobaczyc CUDZE zamowienie

